open class Base {
    init {
        try { println("Base sees ${describe()}") }
        catch (e: Exception) { println("Base init threw ${e::class.simpleName}") }
    }
    open fun describe() = "base"
}

class Child : Base() {
    val name by lazy { "child" }
    override fun describe() = "name=$name"
}

fun main() {
    val c = Child()
    println(c.describe())
}

